def create_conversation_moderator_group(apps, schema_editor):
    content_type_model = apps.get_model("contenttypes", "ContentType")
    group_model = apps.get_model("auth", "Group")
    permission_model = apps.get_model("auth", "Permission")
    content_type, _ = content_type_model.objects.get_or_create(
        app_label="communications",
        model="conversationreport",
    )
    permission, _ = permission_model.objects.get_or_create(
        content_type=content_type,
        codename="moderate_conversation_reports",
        defaults={"name": "Can moderate Conversation Reports"},
    )
    group, _ = group_model.objects.get_or_create(name="Conversation Moderator")
    group.permissions.add(permission)


def remove_conversation_moderator_group(apps, schema_editor):
    group_model = apps.get_model("auth", "Group")
    group_model.objects.filter(name="Conversation Moderator").delete()


